\label{Conj1}
Let $\varphi:\mathbb{R} \to\mathbb{R}$ be non-negative, radial decreasing, and with $\int_{\mathbb{R}}\varphi(x) \mathop{}\!\mathrm{d} x = 1$. Then, for any $f:\mathbb{R} \to \mathbb{R}$ of bounded variation, we have
\begin{equation}\label{20260213_17:30}
\operatorname{Var}(\mathrm M_{\varphi}f) \leq \operatorname{Var}(f).
\end{equation}

\label{Conj3}
Let $\varphi:\mathbb{R}^d \to\mathbb{R}$ be non-negative, radial decreasing, and with $\int_{\mathbb{R}^d}\varphi({\bm{x}}) \mathop{}\!\mathrm{d} {\bm{x}} = 1$. Then, for any $f \in \mathrm{BV}(\mathbb{R}^d)$, we have
\begin{equation}\label{20260213_17:41}
\operatorname{Var}(\mathrm M_{\varphi}f) \leq C_d \operatorname{Var}(f)\,,
\end{equation}
where $C_d$ is a constant depending only on the dimension $d$.

\label{Thm4}
For $B_1 \subset \mathbb{R}^d$ and ${\bm{x}} \in \mathbb{R}^d$ with $|{\bm{x}}|> 1$ we have
\begin{equation}\label{20260320_15:03}
\mathrm M\chi_{B_1}({\bm{x}}) \sim |{\bm{x}}|^{-d} \left( 1 + \frac{\sqrt{d}}{\left( |{\bm{x}}| + \frac{1}{\sqrt{|{\bm{x}}| -1}}\right)}\right)^{-1}\,,
\end{equation}
with the implicit constant being universal.

\label{Cor5}
For $B_1 \subset \mathbb{R}^d$ we have
\begin{equation*}
\frac{\operatorname{Var}(\mathrm M\chi_{B_1})}{\operatorname{Var}(\chi_{B_1})} \sim \sqrt{d} \, \log d.
\end{equation*}

\label{Cor1.6_growth}
The constant $C_d$ in \zcref{Conj3} must verify
\begin{equation*}
C_d \gtrsim \sqrt{d} \, \log d.
\end{equation*}

\label{Lemma_Reg_dim_1}
Let $-1\leq x<y\leq 1$.
Then
\begin{align}\label{20260417_17:32}
\big| \mathrm M_\varphi f(y) - \mathrm M_\varphi f(x)\big| \leq y\mathrm M_\varphi f(y) - x\mathrm M_\varphi f(x).
\end{align}

We first prove the upper bound in \zcref{20260417_17:32}. It clearly holds when $y=1$, so we may assume that $-1 \leq x < y < 1$.
Let $r>0$.
The plan is to compare $f*\varphi_r(y)$ with $f*\varphi_{\tilde r}(x)$ for
\(
\tilde r
=
\big(\frac{1-x}{1-y}\big)r
>
r.
\)
For all $t \leq -1$ we have
\begin{align*}
0\leq   \frac{x-t}{\tilde r} \leq \frac{x-t}r \leq \frac{y-t}r.
\end{align*}
For all $t\geq1$ we have
\begin{align*}
0 \geq \frac{x-t}{\tilde r} = \left(\frac{x-t}r\right)
\left(\frac{1-y}{1-x}\right) \geq  \left(\frac{x-t}r\right)
\left(\frac{t-y}{t-x}\right) = \frac{y-t}r.
\end{align*}

