Since $f\equiv0$ on $(-1,1)$ and $\varphi$ is decreasing away from $0$, for all $t\in\mathbb{R}$ we can conclude that 
\[
f(t)\,
\varphi\!\left(
\frac{x-t}{\tilde r}
\right)
\geq
f(t)\,
\varphi\!\left(
\frac{y-t}r
\right)
.
\]
Therefore,
\[
\mathrm M_\varphi f(x)
\geq
\frac1{\tilde r}
\int_{\mathbb{R}}
f(t)\,
\varphi\!\left(
\frac{x-t}{\tilde r}
\right)
\mathop{}\!\mathrm{d} t
\geq
\left(\frac{1-y}{1-x}\right)
\frac1r
\int_{\mathbb{R}}
f(t)\,
\varphi\!\left(
\frac{y-t}r
\right)
\mathop{}\!\mathrm{d} t.
\]
Taking the supremum over all $r>0$ we conclude that 
\[
\mathrm M_\varphi f(x)
\geq
\left(\frac{1-y}{1-x}\right)
\mathrm M_\varphi f(y)\,,
\]
which is equivalent to the desired upper bound
\[
\mathrm M_\varphi f(y) - \mathrm M_\varphi f(x)
\leq
y\mathrm M_\varphi f(y) - x\mathrm M_\varphi  f(x).
\]
To conclude the lower bound define $\tilde{f} = f(-\, \cdot)$, $\tilde{\varphi} = \varphi(-\, \cdot)$, $\tilde x=-y$ and $\tilde y=-x$.
Then \(\mathrm M_{\tilde{\varphi}}(\tilde{f})(\tilde{x})=\mathrm M_\varphi f(-\tilde{x})=\mathrm M_\varphi f( y)\), and we obtain the lower bound in \zcref{20260417_17:32} by inserting those quantities for $f,\varphi,x,y$ in the upper bound.
This concludes the proof of \zcref{20260417_17:32}.

\label{Cor_Lipschitz}
The function $\mathrm M_{\varphi}f$ is locally Lipschitz in $(-1,1)$ and for almost all $ x \in (-1,1)$ we have the pointwise bound
\begin{align*}
-\frac{\mathrm M_{\varphi}f (x)}{1+x} \leq \big(\mathrm M_{\varphi}f\big)'(x) \leq \frac{\mathrm M_{\varphi}f (x)}{1-x}.
\end{align*}

\zcref[S]{20260417_17:32} can be reformulated as
\[
-\frac{\mathrm M_{\varphi}f (x)}{1+y}
\leq
\frac{
\mathrm M_\varphi f(y)
-
\mathrm M_\varphi f(x)
}{y-x}
\leq
\frac{\mathrm M_{\varphi}f (y)}{1-x}\,,
\]
and we finish the proof by letting $y\rightarrow x$.

\label{Lemma12_Abs_cont}
Let $g:[0,1) \to \mathbb{R}_{\geq 0}$ be a locally absolutely continuous function such that 
\begin{equation}\label{20260508_17:06}
\frac{-g(x)}{1+x} \leq g'(x) \leq \frac{g(x)}{1-x}
\end{equation}
for each $x \in [0,1)$. Then, for each $x \in [0,1)$, 
$$\int_0^x |g'(y)|  \mathop{}\!\mathrm{d} y \leq x \, g(x).$$

\label{Lemma3.1_Em}
With notations as above, if $b_{n-1} \leq x < a_n$ and $0 < \delta \leq  a_n - x$ we have 
\begin{align}\label{20260903_11:10}
- \,\frac{\delta\sqrt d}{x - b_{n-1}} -  \,\frac{\delta\sqrt d}{ \sqrt{a_n^2 - \big(x + \frac{\delta}{2}\big)^2}}  \ \lesssim \ \Delta^\delta(\mathrm M_{\varphi} f)(x\bm{e}) \  \lesssim \ \frac{\delta\sqrt d}{a_n-x - \delta}.
\end{align}

By the sublinearity of the maximal operators and \zcref{20260903_10:54}, we have
\begin{align}\label{20260903_11:09}
\begin{split}
- \mathrm M^{\mathrm s} \left(-\Delta^\delta f\right)(x\bm{e})   \leq - \mathrm M^{\mathrm s}_{\varphi} \left(-\Delta^\delta f\right)(x\bm{e})  & \leq \Delta^\delta(\mathrm M_{\varphi} f)(x\bm{e})  =  \Delta^\delta(\mathrm M^{\mathrm s}_{\varphi} f)(x\bm{e}) \\
 & \leq \mathrm M^{\mathrm s}_{\varphi} \left(\Delta^\delta f\right)(x\bm{e}) \leq   \mathrm M^{\mathrm s} \left(\Delta^\delta f\right)(x\bm{e}).
\end{split}
\end{align}
Hence, in light of \zcref{20260903_11:09}, it suffices to consider the signed Hardy-Littlewood maximal operator in order to establish \zcref{20260903_11:10}.


Write \(f= f_1 + f_2\), where \(f_1 = f\cdot \chi_{B(\bm{0},b_{n-1})}\) and \(f_2 = f\cdot \chi_{\mathbb{R}^d\setminus B(\bm{0},a_n)}\).
\begin{figure}[htbp]
\centering

\caption{For $f_1 = f\cdot \chi_{B(\bm{0},b_{n-1})}$ and $x+\delta/2\geq b_{n-1}$ we have $f_1*(\Delta^{\delta}\chi_{B(\bm{0},r)})(x\bm{e})\leq0$.}
\label{decrease}
\end{figure}
Recalling \zcref{20260905_19:10}, note that for any $r >0$
\begin{align}\label{20260903_11:23}
\begin{split}
\big(\Delta^\delta f_1*\chi_{B(\bm{0},r)}\big)(x\bm{e})
& = f_1*\big(\Delta^\delta \chi_{B(\bm{0},r)}\big)(x\bm{e}) \\
& = \int_{\mathbb{R}^{d}} f_1({\bm{y}}) \left( \chi_{B((x+\delta) \bm{e}, r)}({\bm{y}}) -  \chi_{B(x \bm{e}, r)}({\bm{y}})\right) \mathop{}\!\mathrm{d} {\bm{y}} \leq 0\, ,
\end{split}
\end{align}
see \zcref{decrease}.
Also, note that $\big(\Delta^{\delta}f_2*\chi_{B(\bm{0},r)}\big)(x\bm{e}) = 0$ if $r < a_n - x - \delta$. Hence, in order to get a non-trivial average of $\Delta^\delta f_2$ one must consider a radius $r \geq a_n - x - \delta$. From \zcref{20260903_11:23} and \zcref{gradientawayfromsupport1} we get 
\begin{align*}
 \mathrm M^{\mathrm s} \left(\Delta^\delta f\right)(x\bm{e}) \leq \mathrm M^{\mathrm s} \left(\Delta^\delta f_2\right)(x\bm{e})\lesssim \frac{\delta\sqrt d}{a_n-x - \delta}.
\end{align*}
This establishes the inequality on the right-hand side of \zcref{20260903_11:10}.

Similarly, observe that $\big(\Delta^\delta f_1*\chi_{B(\bm{0},r)}\big)(x\bm{e}) = 0$ if $r <  x - b_{n-1}$. From \zcref{gradientawayfromsupport1} we plainly get 
\begin{align}\label{20260903_12:42}
 -\mathrm M^{\mathrm s} \left(-\Delta^\delta f_1\right)(x\bm{e}) \gtrsim - \,\frac{\delta\sqrt d}{x - b_{n-1}}.
\end{align}
\begin{figure}[htbp]
\centering

\caption{For \(f_2 = f\cdot \chi_{\mathbb{R}^d\setminus B(\bm{0},a_n)}\), if $r\leq\sqrt{(\delta/2)^2+a_n^2-(x+\delta/2)^2}$ then $f_2*(\Delta^{\delta}\chi_{B(\bm{0},r)})(x\bm{e})\geq0$.}
\label{sqrtincrease}
\end{figure}

\noindent Finally, observe that if $r < \sqrt{\big(\frac{\delta}{2}\big)^2+ a_n^2 - \big(x + \frac{\delta}{2}\big)^2}$, then $B(x\bm{e}, r) \setminus H\big(x + \frac{\delta}{2}\big)$ does not intersect $\mathbb{R}^d \setminus B(\bm{0},a_n)$ and hence, recalling \zcref{20260905_19:10},
\begin{align*}
\big(-\Delta^\delta f_2*\chi_{B(\bm{0},r)}\big)(x\bm{e}) & = f_2*\big(-\Delta^\delta \chi_{B(\bm{0},r)}\big)(x\bm{e})\\
& =  \int_{\mathbb{R}^{d}} f_2({\bm{y}}) \left( \chi_{B(x \bm{e}, r)}({\bm{y}}) -  \chi_{B((x+ \delta) \bm{e}, r)}({\bm{y}})\right) \mathop{}\!\mathrm{d} {\bm{y}} \leq 0\,,
\end{align*}
see \zcref{sqrtincrease}.
From \zcref{gradientawayfromsupport1} we then get 
\begin{align}\label{20260903_12:43}
 -\mathrm M^{\mathrm s} \left(-\Delta^\delta f_2\right)(x\bm{e}) \gtrsim - \,\frac{\delta\sqrt d}{ \sqrt{\big(\frac{\delta}{2}\big)^2+ a_n^2 - \big(x + \frac{\delta}{2}\big)^2}} \geq - \,\frac{\delta\sqrt d}{ \sqrt{ a_n^2 - \big(x + \frac{\delta}{2}\big)^2}}.
\end{align}
Putting together \zcref{20260903_12:42} and \zcref{20260903_12:43} we arrive at the inequality on the left-hand side of \zcref{20260903_11:10}.

\label{pro_capvolume}
For $t\geq0$ we have
\[
C(t)
\sim
\frac{
(1-t^2)^{\frac{d+1}2}
}{
t \sqrt d +1
}
,
\]
with the implicit constant being universal.

The result is trivial for $d=1$, so we may assume that $d>1$ here. Observe that the integrand $g(s)^{d-1}$ in \zcref{20260805_14:52} is a decreasing function for $s\geq 0$.
The idea is to show that the whole integral in $C(t)$ is dominated by the integral from $t$ to $t+\varepsilon(t)$, with $\varepsilon(t)$ such that $g(t+\varepsilon(t))^{d-1}$ is approximately half of $g(t)^{d-1}$.
Then we will be able to conclude $C(t)\sim(\omega_{d-1}/\omega_d)\varepsilon(t)g(t)^{d-1}$.
Note that $g^{d-1}$ approximately halves if and only if $g$ shrinks by a factor of $1-1/d$.
For $0 \leq t <1$, in order to find $\varepsilon(t)$ that achieves this, we estimate the derivative of $g$ on $[t,t+\eta]$, where 
\begin{equation}\label{20260610_17:39}
\eta:=\min\left\{d^{-\frac12}\,,\,\frac{1-t}2\right\}
\end{equation}
is an upper bound for $\varepsilon(t)$, as we will see. 
Since
\(
g'(s)
=
-\frac s{(1-s^2)^{1/2}}
\)
is decreasing, we can take $g'(t)$ as an upper bound for $g'$ on $[t,t+\eta]$.
We will show that
\[
h(t)
:=
-\frac{2\big(t+d^{-\frac12}\big)}{(1-t^2)^{\frac12}}
,
\]
which is decreasing as well, is a lower bound for $g'$ on $[t,t+\eta]$.
To that end, it suffices to estimate
\begin{align*}
\frac{g'(t+\eta)}{h(t)}
=
\frac{t+\eta}{2\big(t+d^{-\frac12}\big)}
\left(
\frac{1-t}{1-t-\eta}\right)^{\frac12}\left(\frac{1+t}{1+t+\eta}
\right)^{\frac12}
\leq \frac{t+\eta}{2\big(t+d^{-\frac12}\big)}
\left(
\frac{1-t}{1-t-\eta}\right)^{\frac12} \leq  \frac{\sqrt{2}}{2} < 1\,,
\end{align*}
where we have used \zcref{20260610_17:39}. We can now define
\[
\varepsilon(t)
:=
 - \frac{
g(t)
}{
d\, h(t)
}
=
\frac{
1-t^2
}{
2d\big(t+d^{-\frac12}\big)
}
,
\]
and one can check that 
\(
\varepsilon(t)
\leq \eta
\).
Hence, for all $t\leq s\leq t+\varepsilon(t)$, we conclude that  
\begin{equation}
\label{gdirectlowerbound}
g(s)-g(t)
\geq
(s-t)g'(s)
\geq
\varepsilon(t)h(t)
=
-\frac{
g(t)
}d
.
\end{equation}
From \zcref{gdirectlowerbound} and the elementary inequality 
\begin{equation}\label{20260805_14:14}
\left(1 - \frac{1}{d}\right)^{d-1} \geq e^{-1}\,,
\end{equation} 
valid for $d>1$, we get 
\begin{equation}\label{20260805_14:02}
\frac{\omega_d}{\omega_{d-1}}
C(t)
\geq
\int_t^{t+\varepsilon(t)}
g(t)^{d-1}
\left(
1-\frac1d
\right)^{d-1}
\mathop{}\!\mathrm{d} s
\geq
e^{-1}\,\varepsilon(t)\,g(t)^{d-1}.
\end{equation}
This plainly yields
\[
C(t)
\gtrsim
\frac{
(1-t^2)^{\frac{d+1}2}
}{
t \sqrt d +1
}
.
\]


To prove the upper bound, note that 
\(
\max\{\varepsilon(t),t\}
\geq
\frac1{
3\sqrt{d}
}\,,
\)
which implies \(t+\frac{\varepsilon(t)}{2}\gtrsim t+d^{-\frac12}\). Hence, there exists a universal $c$, with $0<c < 1$, such that 
$$-g'\Big(t+\tfrac{\varepsilon(t)}{2}\Big)\geq-2\,c\,h(t).$$
From this we get
\[
g(t)-g\big(t+\varepsilon(t)\big)
\geq
g\Big(t+\tfrac{\varepsilon(t)}{2}\Big)-g\big(t+\varepsilon(t)\big)
\geq
-
\frac{
\varepsilon(t)
}2
g'\Big(t+\tfrac{\varepsilon(t)}{2}\Big)
\geq
-c\,\varepsilon(t)
\,h(t)
=
\frac{
c\,g(t)
}d\,,
\]
which means
\begin{equation}\label{20260819_21:34}
g\big(t+\varepsilon(t)\big)
\leq
\left(1 - \frac{c}{d} \right)
g(t)
.
\end{equation}
Since $\varepsilon(t)$ and $g(t)$ are decreasing in $t$, we can conclude inductively that 
\begin{align}\label{20260610_21:39}
g\big(t+k\varepsilon(t)\big)
\leq
\left(
1
-
\frac cd
\right)
^k
g(t)
\end{align}
for all $k \geq 0$ such that $t+k\varepsilon(t) \leq 1$. Using again the fact that $g$ is decreasing, splitting the integral defining $C(t)$ into blocks of size $\varepsilon(t)$, and invoking \zcref{20260610_21:39}, we arrive at
\begin{align}\label{20260610_21:34}
\frac{\omega_d}{\omega_{d-1}}
C(t)
&\leq
\sum_{k=0}^{\lfloor(1-t)/\varepsilon(t)\rfloor }
\varepsilon(t)
\,g\big(t+k\varepsilon(t)\big)^{d-1}
\leq
\varepsilon(t)\, g(t)^{d-1}
\sum_{k=0}^{\lfloor(1-t)/\varepsilon(t)\rfloor }
\left(
1
-
\frac cd
\right)
^{(d-1)k}.
\end{align}
From the elementary inequality $(1 - \frac{c}{d})^{d} \leq e^{-c}$ we get 
\begin{align}\label{20260610_21:35}
\sum_{k=0}^\infty
\left(
1
-
\frac cd
\right)
^{(d-1)k}
=
\sum_{k=0}^\infty
\left(
1
-
\frac cd
\right)
^{d\frac{(d-1)k}{d}}
\leq
\sum_{k=0}^\infty
e^{-c\frac{(d-1)k}{d}}
\leq
\sum_{k=0}^\infty
e^{-ck/2}
\lesssim
1
.
\end{align}
From \zcref{20260610_21:34} and \zcref{20260610_21:35} we conclude that 
\[C(t)
\lesssim
\frac{
(1-t^2)^{\frac{d+1}2}
}{
t\sqrt d +1
}
.
\]

\label{lem_capvolumedisturbance}
As before, let 
\begin{equation}\label{20260807_16:53}
\varepsilon(t)
=
\frac{
1-t^2
}{
2d\big(t+d^{-\frac12}\big)
}.
\end{equation}
Let $0\leq t<s<1$, with $s\leq 2t$ and $1-s^2\geq(1-t^2)/2$.
Then
\begin{equation}\label{20260805_14:09}
C(s)
\gtrsim
e^{-\frac{8(s-t)}{\varepsilon(t)}}
C(t)
.
\end{equation}

If $d=1$ the verification is straightforward. We henceforth assume $d>1$. Note that the assumptions on $s$ and $t$ imply that $\varepsilon(t)\geq \varepsilon(s)\geq\varepsilon(t)/4$.

Let $t_0:=t$ and $t_{k+1}:=t_k+\varepsilon(t_k)$.
By induction, \zcref{gdirectlowerbound} and \zcref{20260819_21:34} imply
\begin{equation}\label{20260819_21:38}
\left(1-\frac{c}{d}\right)^k
g(t) \geq g(t_k)
\geq
\left(1-\frac1d\right)^k
g(t)
.
\end{equation}
In particular, note from \zcref{20260819_21:38} that $t_k \to 1$ as $k \to \infty$. Take $k$ such that $t_k\leq s< t_{k+1}$. If $k =0$,
\begin{equation}\label{20260819_21:46}
g(s) \geq g(t_1) \geq \left(1-\frac1d\right)
g(t),
\end{equation}
and from \zcref{20260805_14:02}, \zcref{20260819_21:46}, \zcref{20260610_21:34} and \zcref{20260610_21:35} we get
\begin{align*}
\frac{\omega_d}{\omega_{d-1}}
C(s)
&\gtrsim
g(s)^{d-1}\varepsilon(s)
\gtrsim
g(t)^{d-1}\varepsilon(t)
\gtrsim
\frac{\omega_d}{\omega_{d-1}}
C(t)\,,
\end{align*}
which is \zcref{20260805_14:09} in this case. 

If $k\geq1$, note that 
\begin{equation}\label{20260819_21:53}
s-t\geq t_k-t\geq k \varepsilon(s) \geq k\varepsilon(t)/4\geq(k+1)\varepsilon(t)/8\,,
\end{equation}
and thus, from \zcref{20260819_21:38} and \zcref{20260819_21:53}, 
\begin{align*}
g(s)
&\geq
g(t_{k+1})
\geq
\left(1-\frac1d\right)^{k+1}
g(t)
\geq
\left(1-\frac1d\right)^{\frac{8(s-t)}{\varepsilon(t)}}
g(t)
\geq
e^{-\frac{8(s-t)}{(d-1)\varepsilon(t)}}
g(t)\,,
\end{align*}
where we have used \zcref{20260805_14:14} in the last inequality. The previous estimate, in light of \zcref{20260805_14:02}, \zcref{20260610_21:34} and \zcref{20260610_21:35}, yields
\begin{align*}
\frac{\omega_d}{\omega_{d-1}}
C(s)
&\gtrsim
g(s)^{d-1}\varepsilon(s)
\gtrsim
e^{-\frac{8(s-t)}{\varepsilon(t)}}
g(t)^{d-1}\varepsilon(t)
\gtrsim
e^{-\frac{8(s-t)}{\varepsilon(t)}}
\frac{\omega_d}{\omega_{d-1}}
C(t)\,,
\end{align*}
as desired.

